//! 🧺️ A batch consumer retains every original numerical packet until the caller admits closure and ACK.
use super::*;
use semio_framework_value::{RetainedCloneStep,ValueRefusalKind};
#[derive(Clone,Copy,PartialEq,Eq)]
struct Source{operation:semio_framework_job::OperationId,generation:Generation,payload:semio_framework_job::OriginalPayloadSourceIdentity,clock:Option<u64>,clock_source:usize,deadline:u64}
impl Source{fn borrow(cx:&StepContext<'_>)->Self{Self{operation:cx.operation(),generation:cx.generation(),payload:cx.payload_authority_identity(),clock:cx.original_clock_binding(),clock_source:cx.clock_source()as usize,deadline:cx.original_absolute_deadline_us()}}}
/// 🫴️ Adopts an existing numerical job; its caller remains the source of every later work and retirement opportunity.
pub struct EnergyBatchRun{job:EnergyJob,source:Source,preview:Option<EnergyWirePacket>,checkpoint:Option<EnergyWireLease>,commit:Option<EnergyWireLease>,fault:Option<EnergyWireLease>,terminal:Option<EnergyRun>,closing:bool}
impl EnergyBatchRun{
 pub fn admit(input:&mut Option<EnergyJob>,output:&mut Option<Self>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if output.is_some(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy batch output slot is occupied").into())}let job=input.as_ref().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy batch original numerical input is absent"))?;if !job.authority.as_deref().is_some_and(|job|!job.closing&&job.stage==EnergyJobStage::Validate&&job.input_identity.is_pristine()){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy batch input must retain its pristine unbound numerical receiver").into())}if job.operation.operation!=cx.operation()||job.operation.generation!=cx.generation(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy batch retains its unmatched original candidate").into())}if cx.is_cancelled()||cx.should_yield(){return Ok(false)}let source=Source::borrow(cx);Self::metadata(cx,size_of::<Self>()+size_of::<Option<EnergyJob>>(),||{*output=Some(Self{job:input.take().unwrap(),source,preview:None,checkpoint:None,commit:None,fault:None,terminal:None,closing:false});Ok(())})}

 fn validate(&self,cx:&StepContext<'_>)->Result<(),ValueError>{if self.source==Source::borrow(cx){Ok(())}else{Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy batch requires its same original source, clock and decoder"))}}
 fn metadata(cx:&mut StepContext<'_>,bytes:usize,advance:impl FnOnce()->Result<(),ValueError>)->Result<bool,OriginalTurnFailure>{let mut admitted=false;semio_framework_job::close_original_retained_step(cx,RetirementDemand{copy_bytes:bytes,depth:1,..Default::default()},|_|{advance()?;admitted=true;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()}))})?;Ok(admitted)}
 fn retire_pending(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if let Some(packet)=self.preview.as_mut(){if !packet.terminal_is_empty(){let demand=packet.retirement_demands()?;semio_framework_job::close_original_retained_step(cx,demand,|loan|packet.close_step(loan))?;}else{Self::metadata(cx,size_of::<Option<EnergyWirePacket>>(),||{drop(self.preview.take());Ok(())})?;}return Ok(true)}
  for kind in [EnergyWireKind::Checkpoint,EnergyWireKind::Commit,EnergyWireKind::Fault]{let slot=match kind{EnergyWireKind::Checkpoint=>&mut self.checkpoint,EnergyWireKind::Commit=>&mut self.commit,EnergyWireKind::Fault=>&mut self.fault,_=>unreachable!()};let Some(lease)=slot.as_mut()else{continue};if !lease.packet().terminal_is_empty(){let demand=lease.packet().retirement_demands()?;semio_framework_job::close_original_retained_step(cx,demand,|loan|lease.packet_mut().close_step(loan))?;}else{let job=&mut self.job;Self::metadata(cx,size_of::<Option<EnergyWireLease>>(),||{let original=slot.take().unwrap();let result=match kind{EnergyWireKind::Checkpoint=>job.ack_checkpoint_packet(original),EnergyWireKind::Commit=>job.ack_commit_packet(original),EnergyWireKind::Fault=>job.ack_fault_packet(original),_=>unreachable!()};if let Err(original)=result{*slot=Some(original);return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy batch ACK retained its original rejected lease"))}Ok(())})?;}return Ok(true)}Ok(false)
 }
 fn capture_packet(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  let generation=self.job.operation.generation;
  if self.job.publication.preview.is_some(){Self::metadata(cx,size_of::<Option<EnergyWirePacket>>(),||{self.preview=self.job.take_preview_packet(generation).map_err(|_|ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy preview source generation changed"))?;Ok(())})?;return Ok(true)}
  for kind in [EnergyWireKind::Checkpoint,EnergyWireKind::Commit,EnergyWireKind::Fault]{let queued=match kind{EnergyWireKind::Checkpoint=>if self.job.publication.checkpoints.in_flight.is_none(){self.job.publication.checkpoints.len}else{0},EnergyWireKind::Commit=>if self.job.publication.commits.in_flight.is_none(){self.job.publication.commits.len}else{0},EnergyWireKind::Fault=>if self.job.publication.faults.in_flight.is_none(){self.job.publication.faults.len}else{0},_=>0};if queued==0{continue}Self::metadata(cx,size_of::<Option<EnergyWireLease>>(),||{let packet=match kind{EnergyWireKind::Checkpoint=>self.job.take_checkpoint_packet(generation),EnergyWireKind::Commit=>self.job.take_commit_packet(generation),EnergyWireKind::Fault=>self.job.take_fault_packet(generation),_=>unreachable!()}.map_err(|_|ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy batch queue source generation changed"))?;match kind{EnergyWireKind::Checkpoint=>self.checkpoint=packet,EnergyWireKind::Commit=>self.commit=packet,EnergyWireKind::Fault=>self.fault=packet,_=>unreachable!()}Ok(())})?;return Ok(true)}Ok(false)
 }
 /// ⏱️ Advances one caller-funded numerical or original packet frontier without creating source authority.
 pub fn step(&mut self,cx:&mut StepContext<'_>)->Result<EnergyRun,OriginalTurnFailure>{self.validate(cx)?;if self.closing||cx.should_yield(){return Ok(EnergyRun::Yield)}if self.retire_pending(cx)?||self.capture_packet(cx)?{return Ok(EnergyRun::Yield)}if let Some(terminal)=self.terminal{return Ok(terminal)}let observed=match self.job.step(cx)?{None|Some(JobOutcomeBorrow::Yield{..})=>EnergyRun::Yield,Some(JobOutcomeBorrow::PreviewReady{..})=>EnergyRun::Preview,Some(JobOutcomeBorrow::CheckpointReady{applied_progress,..})=>EnergyRun::Checkpoint(applied_progress),Some(JobOutcomeBorrow::Complete{..})=>EnergyRun::Complete,Some(JobOutcomeBorrow::Fault{..})=>EnergyRun::Fault,Some(JobOutcomeBorrow::Cancelled{..})=>EnergyRun::Cancelled};if matches!(observed,EnergyRun::Complete|EnergyRun::Fault|EnergyRun::Cancelled){self.terminal=Some(observed)}Ok(observed)}
 /// 📤️ A completed result moves once into the caller's retained output slot.
 pub fn take_results(&mut self,output:&mut Option<Results>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if output.is_some(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy result output slot is occupied").into())}if self.closing||cx.is_cancelled()||cx.should_yield()||self.terminal!=Some(EnergyRun::Complete){return Ok(false)}if self.job.result.is_none(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy batch typed result has already transferred").into())}Self::metadata(cx,size_of::<Option<Results>>(),||{*output=self.job.take_results();Ok(())})}
 pub fn begin_close(&mut self){self.closing=true;}
 /// ♻️ Pending leases keep custody until the same caller closes and ACKs them, then closes the numerical job.
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{self.validate(cx)?;self.begin_close();let before=cx.retained_progress();if self.retire_pending(cx)?{let after=cx.retained_progress();let progress=RetainedCloneProgress{copied_items:after.copied_items-before.copied_items,copied_bytes:after.copied_bytes-before.copied_bytes,retained_capacity_bytes:after.retained_capacity_bytes-before.retained_capacity_bytes,released_bytes:after.released_bytes-before.released_bytes};return Ok(InteractiveJobCloseStep::Pending{progress})}self.job.close_step(cx)}
 pub fn terminal_is_empty(&self)->bool{self.job.terminal_is_empty()&&self.preview.is_none()&&self.checkpoint.is_none()&&self.commit.is_none()&&self.fault.is_none()}
}

